import json

with open('/home/USER/runs/paper/qwen-h-in-glm-hpl-u1/frozen/seen-7/play/users/u059/system/state/workspace/programs/task-0f6e5a2f.json', 'r') as f:
    task = json.load(f)

print("=== TASK INPUT COLORS (first demo) ===")
input_grid = task[0]['input']
output_grid = task[0]['output']

all_colors = set()
for row in input_grid:
    all_colors.update(row)
print("Input colors:", sorted(all_colors))

for row in output_grid:
    all_colors.update(row)
print("Output colors:", sorted(all_colors))

# Find which colors changed
changes = {}
for r, row in enumerate(input_grid):
    for c, val in enumerate(row):
        out_val = output_grid[r][c]
        if val != out_val:
            if val not in changes:
                changes[val] = []
            changes[val].append(out_val)

print("\n=== COLOR CHANGES (task input) ===")
for k, v in sorted(changes.items()):
    print(f"{k} -> {sorted(set(v))}")
